import subprocess, itertools

def run(args):
    r = subprocess.run(['./executable']+args, capture_output=True, text=True)
    return r.stdout, r.stderr, r.returncode

global_opts = ['--version','--license','--help','--json-usage','--drivers']
# Test pairwise priority
pairs = list(itertools.permutations(global_opts, 2))
for a,b in pairs:
    out,err,rc = run([a,b])
    # classify output
    if out.startswith('GDAL'):
        got = '--version'
    elif 'GDAL/OGR Licensing' in out:
        got = '--license'
    elif out.startswith('Usage:'):
        got = '--help'
    elif out.startswith('{'):
        got = '--json-usage'
    elif out.startswith('['):
        got = '--drivers'
    else:
        got = 'unknown:'+out[:30]
    print(f"{a} + {b} => {got} (a={a} b={b}) rc={rc}")

# Test triple
print("--- triples with version license help ---")
for perm in itertools.permutations(['--version','--license','--help']):
    out,_,_ = run(list(perm))
    if 'Licensing' in out:
        g='license'
    elif out.startswith('GDAL'):
        g='version'
    elif out.startswith('Usage'):
        g='help'
    else:
        g='other'
    print(perm, "=>", g)

